WHERE general_ledgers.is_active = 1
AND ( general_ledgers.`reference` LIKE CONCAT('%', #{filter.reference}, '%') OR general_ledgers.`note` LIKE CONCAT('%', #{filter.reference}, '%') OR general_ledgers.id IN ( SELECT gld.general_ledger_id FROM general_ledger_details gld LEFT JOIN chart_accounts ca ON ca.id = gld.chart_account_id WHERE ( ca.account_description LIKE CONCAT('%', #{filter.reference}, '%') OR ca.account_codes LIKE CONCAT('%', #{filter.reference}, '%') OR gld.memo LIKE CONCAT('%', #{filter.reference}, '%') OR CAST(gld.debit AS CHAR) LIKE CONCAT('%', #{filter.reference}, '%') OR CAST(gld.credit AS CHAR) LIKE CONCAT('%', #{filter.reference}, '%') ) ) OR general_ledgers.id IN ( SELECT gld2.general_ledger_id FROM general_ledger_details gld2 LEFT JOIN classes c ON c.id = gld2.class_id WHERE c.name LIKE CONCAT('%', #{filter.reference}, '%') ) )
AND general_ledgers.`is_approve` = #{filter.status}
AND DATE(general_ledgers.date) >= #{filter.dateFrom} AND DATE(general_ledgers.date) <= #{filter.dateTo}
AND general_ledgers.id IN (SELECT general_ledger_id FROM general_ledger_details WHERE company_id = #{filter.companyId})
AND general_ledgers.id IN ( SELECT general_ledger_id FROM general_ledger_details WHERE company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId}) )
AND general_ledgers.id IN (SELECT general_ledger_id FROM general_ledger_details WHERE customer_id = #{filter.customerId})
AND general_ledgers.id IN (SELECT general_ledger_id FROM general_ledger_details WHERE vendor_id = #{filter.vendorId})
AND general_ledgers.id IN (SELECT general_ledger_id FROM general_ledger_details WHERE other_id = #{filter.otherId})
AND general_ledgers.id IN (SELECT general_ledger_id FROM general_ledger_details WHERE class_id = #{filter.classId})
AND general_ledgers.id IN (SELECT general_ledger_id FROM general_ledger_details WHERE chart_account_id = #{filter.chartAccountId})
AND general_ledgers.id IN (SELECT general_ledger_id FROM general_ledger_details WHERE chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_group_id = #{filter.chartAccountGroupId}))
AND (SELECT branch_id FROM general_ledger_details WHERE general_ledger_id=general_ledgers.id LIMIT 1) = #{filter.branchId}
AND general_ledgers.created_by = #{filter.createBy}
AND general_ledgers.`is_approve` = #{filter.status}
AND general_ledgers.recurrence = 1

