SELECT gld.id AS id, gl.id AS journalEntryId, gl.date AS `date`, CONCAT(users1.first_name, ' ', users1.last_name) AS createdBy, gl.reference AS reference, gl.is_adj AS adj, gld.type AS `type`, vendors.name AS vendorName, customers.name AS customerName, (SELECT CONCAT(account_codes, ' · ', account_description) FROM chart_accounts WHERE id = gld.chart_account_id) AS chartAccountName, gld.memo AS description, classes.name AS className, gld.debit AS debit, gld.credit AS credit, IF(gld.debit > 0, gld.debit, gld.credit * -1) AS signedAmount, gl.is_sys AS isSys, gld.company_id AS companyId, gld.chart_account_id AS chartAccountId, gld.customer_id AS customerId, gld.vendor_id AS vendorId, gld.employee_id AS employeeId, gld.class_id AS classId FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id LEFT JOIN users AS users1 ON users1.id = gl.created_by LEFT JOIN vendors ON vendors.id = gld.vendor_id LEFT JOIN customers ON customers.id = gld.customer_id LEFT JOIN classes ON classes.id = gld.class_id
gl.is_active = 1
AND gl.is_approve = #{filter.status}
AND gl.recurrence = 1
AND gl.is_approve = 1
AND DATE(gl.date) >= #{filter.dateFrom}
AND DATE(gl.date) <= #{filter.dateTo}
