AND gld.chart_account_id = #{filter.chartAccountId}
AND gld.company_id = #{filter.companyId}
AND gld.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND gld.customer_id = #{filter.customerId}
AND gld.vendor_id = #{filter.vendorId}
AND gld.other_id = #{filter.otherId}
AND gld.class_id = #{filter.classId}
